import{_ as a,a as n,b as p}from"./chunks/mmad_nongemv_compare.BOQ8MmSm.js";import{_ as l,o as c,a as t,b as e}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"mmad计算关键特性说明","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/mmad_compute_key_features"},{"text":"GEMV","link":"/api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/gemv"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/gemv.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/gemv.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用优势","slug":"使用优势","link":"#使用优势"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1787967772000}'),_={name:"api/SIMD-API/tensor_api/matrix_compute/mmad_compute_key_features/gemv.md"};function o(m,s,r,w,i,d){return c(),t("div",null,[...s[0]||(s[0]=[e('<div><article class="markdown-body"><h1>GEMV</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>GEMV的核心功能体现为：当矩阵A的维度M取值为1时，接口可以手动启用GEMV功能，该操作退化为1×K维度的行向量与K×N维度矩阵之间的乘法运算。</p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT产品，GEMV模式默认关闭。如需启用GEMV模式，需要设置<code>mmad_trait::disable_gemv</code>参数为<code>false</code>。</p></div><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><ul><li><p>1×K矩阵A需满足512B地址对齐，K个数据连续存储。以<code>half</code>类型为例，当K=256时，软件侧可视作16×16分块，配置m=1后硬件解析为1×256向量，可通过<code>copy</code>接口将256个<code>half</code>数据从L1 Buffer搬至L0A Buffer。</p></li><li><p>C矩阵是一个1×N的向量，当1×N向量被划分为多个1×16子向量时，每个子向量在L0C Buffer中占用1024B。但实际有效数据仅占最低32B或64B。例如，当N=50时，共划分4个1×16子向量，占用4×512B=2048B，其中有效数据仅为4×32B=128B。</p></li></ul><p><strong>图1</strong> GEMV模式矩阵乘示意图</p><p><img src="'+a+'" alt="GEMV模式矩阵乘示意图"></p><h2 id="使用优势">使用优势<a class="header-anchor" href="#使用优势">​</a></h2><p>M=1时开启GEMV模式，则矩阵乘法将M方向作为非对齐场景进行处理。GEMV模式相较于非对齐处理方式，搬运数据量更少，性能更好。下面以M=1、K=256、N=32，左右矩阵数据类型为<code>half</code>的矩阵乘示例说明。</p><ul><li><p>GEMV模式</p><p>将A矩阵从L1 Buffer搬运到L0A Buffer时，1×256的向量被当作16×16的矩阵进行处理，调用<code>copy</code>接口一次完成16×16分形大小的矩阵搬运。B矩阵的搬运以及矩阵乘计算跟基础场景相同，如下图所示。</p><p><strong>图2</strong> GEMV模式M=1的矩阵乘计算示意图</p><p><img src="'+n+'" alt="GEMV模式M=1的矩阵乘计算示意图"></p></li><li><p>非GEMV模式</p><p>将A矩阵从L1 Buffer搬运到L0A Buffer时，1×256的向量被当作非对齐矩阵数据进行处理，将M方向对齐到32字节后进行搬运。调用<code>copy</code>接口每次搬运16×16分形大小的矩阵，一共搬运K/16=16次，导致搬运数据量增加，性能相较于GEMV模式差，如下图所示。</p><p><strong>图3</strong> 非GEMV模式M不等于1的矩阵乘计算示意图</p><p><img src="'+p+`" alt="非GEMV模式M不等于1的矩阵乘计算示意图"></p></li></ul><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>本GEMV场景示例的规格如下：</p><p><strong>表1</strong> 使用示例说明</p><table><thead><tr><th>矩阵</th><th>维度大小</th><th>数据类型</th><th>格式</th></tr></thead><tbody><tr><td>A</td><td>1×4096</td><td>half</td><td>ND</td></tr><tr><td>B</td><td>4096×256</td><td>half</td><td>NZ</td></tr><tr><td>C</td><td>1×256</td><td>float</td><td>ND</td></tr></tbody></table><p>通过<a href="../cube_compute_load/copy_gm_to_l1.html">copy</a>接口将输入矩阵A从Global Memory搬运到L1 Buffer上并保持ND格式不变，然后在L1 Buffer上将A矩阵转换为NZ格式，再通过<a href="../cube_compute_load/copy_l1_to_l0a.html">copy</a>接口搬运到L0A Buffer，从而以GEMV模式执行矩阵乘。另外注意GEMV模式默认是关闭的，需要自定义<a href="../mmad_compute/mmad.html">mmad_trait</a>来开启。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>

<span class="k">struct</span><span class="w"> </span><span class="nc">mmad_trait_custom</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="n">trait_type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">mmad_trait</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 设置mmad_trait::disable_gemv参数为false，开启GEMV。</span>
<span class="w">    </span><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">trait_type</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">mmad_trait</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="n">mmad_type</span><span class="o">::</span><span class="n">normal</span><span class="p">);</span>
<span class="p">};</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">mmad_gemv_example</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">a_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">b_gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">c_gm</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="n">a_type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">half</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">4096</span><span class="p">;</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// 数据类型half的c0_element = c0_size(32B) / sizeof(half) = 16，1×K向量按NZ格式重排为(K/c0_element)×c0_element大小的Tensor。</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">c0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">c0_element</span><span class="o">&lt;</span><span class="n">a_type</span><span class="o">&gt;</span><span class="p">;</span>

<span class="w">    </span><span class="n">__cbuf__</span><span class="w"> </span><span class="n">a_type</span><span class="w"> </span><span class="n">l1_a_buf</span><span class="p">[</span><span class="n">m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ca__</span><span class="w"> </span><span class="n">a_type</span><span class="w"> </span><span class="n">l0a_buf</span><span class="p">[</span><span class="n">m</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">k</span><span class="p">];</span>

<span class="w">    </span><span class="c1">// A矩阵Global Memory-&gt;L1 Buffer：ND-&gt;ND，1×K行向量按ND连续搬入L1 Buffer。</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">gm_a_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">a_gm</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1_a_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l1_a_buf</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copy_gm_to_l1_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_gm_to_l1</span><span class="p">{},</span><span class="w"> </span><span class="n">gm_to_l1_trait_default</span><span class="p">{});</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">copy_gm_to_l1_atom</span><span class="p">,</span><span class="w"> </span><span class="n">l1_a_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">gm_a_tensor</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 在L1 Buffer上把这块连续数据重新解释为(K/c0_element)×c0_element大小的NZ分形矩阵（地址不变，仅换layout）。</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l1_a_nz_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">l1_a_tensor</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">a_type</span><span class="o">&gt;</span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">c0</span><span class="p">,</span><span class="w"> </span><span class="n">c0</span><span class="p">));</span>
<span class="w">    </span><span class="c1">// L1 Buffer-&gt;L0A Buffer：NZ-&gt;NZ非转置搬运，一次完成分形搬运。</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">l0a_tensor</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">l0a_buf</span><span class="p">),</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nz_layout_ptn</span><span class="p">,</span><span class="w"> </span><span class="n">a_type</span><span class="o">&gt;</span><span class="p">(</span><span class="n">k</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">c0</span><span class="p">,</span><span class="w"> </span><span class="n">c0</span><span class="p">));</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">copy_l1_to_l0a_atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l1_to_l0a</span><span class="p">{},</span><span class="w"> </span><span class="n">l1_to_l0a_trait_default</span><span class="p">{});</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">copy_l1_to_l0a_atom</span><span class="p">,</span><span class="w"> </span><span class="n">l0a_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">l1_a_nz_tensor</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// B矩阵搬运与基础场景相同（此处省略，假设已得到l0b）。</span>
<span class="w">    </span><span class="c1">// ...</span>

<span class="w">    </span><span class="c1">// mmad计算：使用配置GEMV模式的Trait。</span>
<span class="w">    </span><span class="n">mmad_params</span><span class="w"> </span><span class="nf">params</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">unit_flag_mode</span><span class="o">::</span><span class="n">disable</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_mmad</span><span class="p">(</span><span class="n">mmad_operation</span><span class="p">{},</span><span class="w"> </span><span class="n">mmad_trait_custom</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">params</span><span class="p">);</span>
<span class="w">    </span><span class="n">mmad</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">,</span><span class="w"> </span><span class="n">l0a_tensor</span><span class="p">,</span><span class="w"> </span><span class="n">l0b</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const k=l(_,[["render",o]]);export{h as __pageData,k as default};
